import os, json, numpy as np, sys, glob

sys.path.append('storage/noesis')
try:
    import analyze_contacts as AC
except Exception:
    AC = None
try:
    import seeds_motifs as SM
except Exception:
    SM = None
try:
    import operators as OP
except Exception:
    OP = None
try:
    import operators_integration as OI
except Exception:
    OI = None

N = 26
TOL = 1e-8

def load_saved_best():
    try:
        c = np.loadtxt('storage/noesis/latest_centers.txt')
        r = np.loadtxt('storage/noesis/latest_radii.txt')
        return np.array(c, float).reshape(N,2), np.array(r, float).reshape(N,)
    except Exception:
        return None, None

def grid_plus_hole_seed(r0=0.1 - 1e-8, eps=1e-8):
    coords = [0.1, 0.3, 0.5, 0.7, 0.9]
    centers = [[x, y] for x in coords for y in coords]
    d = float(np.linalg.norm(np.array([0.2,0.2]) - np.array([0.1,0.1])))
    r_hole = d - r0 - eps
    return np.array(centers, float), np.array([r0]*25 + [r_hole], float)

def last_bpigo_op():
    try:
        files = glob.glob('storage/noesis/exports/bpigo_exp_*.json')
        if not files: return None
        files.sort(key=lambda p: os.path.getmtime(p))
        with open(files[-1], 'r') as f:
            data = json.load(f)
        return data.get('op', None)
    except Exception:
        return None

def active_pairs_set(c, r, tol=TOL):
    if AC is None: return None
    _, pairs = AC.active_sets(c, r, tol=tol)
    s = set()
    for (i, j, _) in pairs:
        if i > j: i, j = j, i
        s.add((i, j))
    return s

def jaccard(a, b):
    if a is None or b is None: return None, None, None
    inter = a & b
    uni = a | b
    if len(uni) == 0: return 1.0, 0, 0
    return len(inter)/len(uni), len(inter), len(uni)

def construct_packing():
    # Load baseline (saved best) for return
    c0, r0 = load_saved_best()
    if c0 is None:
        c0, r0 = grid_plus_hole_seed()
    s0 = float(np.sum(r0))

    # If missing modules, log minimal info and return baseline
    if AC is None or OP is None or OI is None:
        try:
            os.makedirs('storage/noesis/exports', exist_ok=True)
            with open('storage/noesis/exports/bpigo_exp2_log.json', 'w') as f:
                json.dump({'status':'modules_unavailable','sum_radii_baseline':s0}, f, indent=2)
        except Exception:
            pass
        return c0, r0

    # Choose complementary operator relative to last BPIGO op
    prev = last_bpigo_op()
    op_name = None
    c_seed, r_seed = c0.copy(), r0.copy()

    try:
        if prev == 'QDF':
            # Complement with Chain Shear along y (slightly conservative amount)
            b_act, _ = AC.active_sets(c0, r0, tol=TOL)
            boundary_idx = set(i for (i, kind, _) in b_act)
            candidates = [(abs(c0[i,1] - 0.5), i) for i in range(N) if i not in boundary_idx]
            candidates.sort()
            chain = [idx for (_, idx) in candidates[:5]] if len(candidates) >= 5 else [i for i in range(5)]
            c_seed, r_seed = OP.chain_shear_seed(c0, r0, chain_idxs=chain, axis='y', amount=1.0e-2)
            op_name = 'ChainShearY_log'
        else:
            # Try QDF with θ≈0.02 if a crossing motif exists
            if SM is not None:
                top_pairs, _ = AC.top_k_bottlenecks(c0, r0, k_pair=14, k_boundary=0)
                cp = SM.find_crossing_pairs(c0, top_pairs) if top_pairs else None
                if cp is not None:
                    (i, j), (k, l) = cp
                    quad = tuple({i, j, k, l})
                    c_seed, r_seed = OP.quad_diagonal_flip_seed(c0, r0, quad_idxs=quad, theta=2.0e-2)
                    op_name = 'QDF_plus_log'
                else:
                    op_name = 'NoCrossing'
            else:
                op_name = 'NoSeedsModule'
    except Exception:
        op_name = 'OpException'

    # Equality‑constrained polish with step≈2e−3; if fails, use seed
    try:
        c_opt, r_opt = OI.polish_preserving_boundary(c_seed, r_seed, tol_eq=TOL, step_c=2e-3, step_r=2e-3, maxiter=600)
    except Exception:
        c_opt, r_opt = c_seed, r_seed

    s1 = float(np.sum(r_opt))
    pairs0 = active_pairs_set(c0, r0, tol=TOL)
    pairs1 = active_pairs_set(c_opt, r_opt, tol=TOL)
    J, inter, uni = jaccard(pairs0, pairs1)

    # Write guaranteed log (bpigo_exp2_log.json)
    try:
        os.makedirs('storage/noesis/exports', exist_ok=True)
        log = {
            'op': op_name,
            'sum_radii_before': s0,
            'sum_radii_after': s1,
            'delta_sum_radii': s1 - s0,
            'pair_jaccard_tol1e8': J,
            'pair_intersection': inter,
            'pair_union': uni,
            'returned': 'baseline'  # always return baseline in this logging‑only run
        }
        with open('storage/noesis/exports/bpigo_exp2_log.json', 'w') as f:
            json.dump(log, f, indent=2)
    except Exception:
        pass

    # Always return baseline for logging‑only
    return c0.astype(float), r0.astype(float)
